"use client";

import * as React from "react";
import { Tabs as BaseTabs } from "@base-ui/react/tabs";
import { cva } from "class-variance-authority";

import { cn } from "@/lib/utils";
import { useAnimatedHeight } from "@/registry/default/hooks/use-animated-height";
import { solidSurface } from "@/registry/default/lib/elevated";

type TabsVariant = "capsule" | "underline";
type TabsSize = "small" | "medium";
type TabsSide = "left" | "right";
type TabsIndicator = "solid" | "raised";

/* -------------------------------------------------------------------------------------------------
 * CVA Variants
 * -------------------------------------------------------------------------------------------------*/

const tabsListVariants = cva(
  [
    "group/tabs-list text-muted-foreground relative z-0 inline-flex w-fit items-center justify-center gap-1",
    "data-[orientation=vertical]:flex-col data-[orientation=vertical]:self-start",
  ],
  {
    variants: {
      variant: {
        capsule: "bg-muted",
        underline:
          "data-[orientation=horizontal]:px-0 data-[orientation=horizontal]:pt-0 data-[orientation=vertical]:py-0",
      },
      size: {
        small: "p-0.5 data-[orientation=horizontal]:gap-x-0.5",
        medium: "p-1 data-[orientation=horizontal]:gap-x-1",
      },
      side: {
        left: "",
        right: "",
      },
    },
    compoundVariants: [
      {
        variant: "capsule",
        size: "small",
        class: "rounded-md",
      },
      {
        variant: "capsule",
        size: "medium",
        class: "rounded-xl",
      },
      {
        variant: "underline",
        side: "left",
        class:
          "data-[orientation=vertical]:**:data-[slot=tabs-trigger]:justify-end",
      },
      {
        variant: "underline",
        side: "right",
        class:
          "data-[orientation=vertical]:**:data-[slot=tabs-trigger]:justify-start",
      },
    ],
    defaultVariants: {
      variant: "capsule",
      size: "medium",
      side: "left",
    },
  },
);

const tabIndicatorVariants = cva(
  [
    "ease-out-expo absolute z-[-1] transition-all duration-200",
    // Vertical orientation
    "data-[orientation=vertical]:top-0 data-[orientation=vertical]:h-(--active-tab-height) data-[orientation=vertical]:translate-y-(--active-tab-top)",
    // Horizontal orientation
    "data-[orientation=horizontal]:left-0 data-[orientation=horizontal]:w-(--active-tab-width) data-[orientation=horizontal]:translate-x-(--active-tab-left) data-[orientation=horizontal]:-translate-y-1/2",
  ],
  {
    variants: {
      variant: {
        underline: [
          "bg-neutral rounded-full",
          "data-[orientation=vertical]:w-0.75",
          "data-[orientation=horizontal]:bottom-0 data-[orientation=horizontal]:top-auto data-[orientation=horizontal]:h-0.75 data-[orientation=horizontal]:translate-y-0",
        ],
        capsule: [
          "data-[orientation=vertical]:w-auto",
          "data-[orientation=horizontal]:top-1/2 data-[orientation=horizontal]:h-(--active-tab-height)",
        ],
      },
      size: {
        small: "",
        medium: "",
      },
      side: {
        left: "",
        right: "",
      },
      // Capsule only: an emphasis-grey chip with a white label (solid), or a
      // lifted chip on the track (raised).
      indicator: {
        solid: "",
        raised: "",
      },
    },
    compoundVariants: [
      { variant: "capsule", indicator: "solid", class: "bg-emphasis" },
      { variant: "capsule", indicator: "raised", class: solidSurface(5, 2) },
      {
        variant: "capsule",
        size: "small",
        class: "rounded-sm data-[orientation=vertical]:inset-x-0.5",
      },
      {
        variant: "capsule",
        size: "medium",
        class: "rounded-md data-[orientation=vertical]:inset-x-1",
      },
      {
        variant: "underline",
        side: "left",
        class: "data-[orientation=vertical]:right-0",
      },
      {
        variant: "underline",
        side: "right",
        class: "data-[orientation=vertical]:left-0",
      },
    ],
    defaultVariants: {
      variant: "capsule",
      size: "medium",
      side: "left",
      indicator: "solid",
    },
  },
);

function Tabs({ className, ...props }: BaseTabs.Root.Props) {
  return (
    <BaseTabs.Root
      data-slot="tabs"
      className={cn(
        "flex min-w-0 gap-2",
        "data-[orientation=vertical]:flex-row",
        "data-[orientation=horizontal]:flex-col",
        className,
      )}
      {...props}
    />
  );
}

function TabsList({
  variant = "capsule",
  size = "medium",
  side = "left",
  indicator = "solid",
  className,
  children,
  ...props
}: BaseTabs.List.Props & {
  variant?: TabsVariant;
  size?: TabsSize;
  side?: TabsSide;
  /** Capsule only: the emphasis-grey chip (solid) or a lifted chip (raised). */
  indicator?: TabsIndicator;
}) {
  return (
    <BaseTabs.List
      data-slot="tabs-list"
      data-variant={variant}
      data-size={size}
      data-side={side}
      data-indicator={variant === "capsule" ? indicator : undefined}
      className={cn(tabsListVariants({ variant, size, side }), className)}
      {...props}
    >
      {children}
      <div
        data-slot="tabs-divider"
        className={cn(
          "bg-accent absolute z-[-2] rounded-full",
          variant === "underline" ? "block" : "hidden",
          // Vertical orientation
          "group-data-[orientation=vertical]/tabs-list:top-0 group-data-[orientation=vertical]/tabs-list:bottom-0 group-data-[orientation=vertical]/tabs-list:w-[2px]",
          side === "left" &&
            "group-data-[orientation=vertical]/tabs-list:right-0 group-data-[orientation=vertical]/tabs-list:-translate-x-[0.5px]",
          side === "right" &&
            "group-data-[orientation=vertical]/tabs-list:left-0 group-data-[orientation=vertical]/tabs-list:translate-x-[0.5px]",
          // Horizontal orientation
          "group-data-[orientation=horizontal]/tabs-list:right-0 group-data-[orientation=horizontal]/tabs-list:bottom-0 group-data-[orientation=horizontal]/tabs-list:left-0 group-data-[orientation=horizontal]/tabs-list:h-[2px] group-data-[orientation=horizontal]/tabs-list:-translate-y-[0.5px]",
        )}
        aria-hidden="true"
      />
      <TabIndicator
        variant={variant}
        size={size}
        side={side}
        indicator={indicator}
      />
    </BaseTabs.List>
  );
}

function TabsTrigger({ className, ...props }: BaseTabs.Tab.Props) {
  return (
    <BaseTabs.Tab
      data-slot="tabs-trigger"
      className={cn(
        // Base styles
        "text-muted-foreground data-active:text-foreground group-data-[indicator=solid]/tabs-list:data-active:text-emphasis-foreground flex cursor-pointer items-center gap-1.5 font-medium text-nowrap whitespace-nowrap",
        // The label color eases over 200ms; the focus ring fades in 100ms.
        "transition-[color,outline-width,outline-color] [transition-duration:200ms,100ms,100ms] ease-out",
        "focus-visible:outline-ring outline-0 -outline-offset-1 outline-transparent outline-solid focus-visible:outline-2",
        "hover:not-data-active:text-muted-foreground/75",
        "data-disabled:pointer-events-none data-disabled:opacity-60",
        "[&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
        // Orientation
        "data-[orientation=horizontal]:flex-1 data-[orientation=vertical]:w-full",
        "justify-center",
        // Default size (small) - overridden by group data attribute for medium
        "rounded-sm px-2 py-1 text-xs",
        // Medium size via parent group
        "group-data-[size=medium]/tabs-list:rounded-md group-data-[size=medium]/tabs-list:px-2.5 group-data-[size=medium]/tabs-list:py-1.5 group-data-[size=medium]/tabs-list:text-sm",
        className,
      )}
      {...props}
    />
  );
}

function TabIndicator({
  variant = "capsule",
  size = "medium",
  side = "left",
  indicator = "solid",
  className,
  ...props
}: BaseTabs.Indicator.Props & {
  variant?: TabsVariant;
  size?: TabsSize;
  side?: TabsSide;
  indicator?: TabsIndicator;
}) {
  return (
    <BaseTabs.Indicator
      data-slot="tab-indicator"
      className={cn(
        tabIndicatorVariants({ variant, size, side, indicator }),
        className,
      )}
      {...props}
    />
  );
}

function TabsPanels({
  className,
  children,
  ...props
}: React.ComponentProps<"div">) {
  const { outerRef, innerRef } = useAnimatedHeight();

  return (
    <div
      ref={outerRef}
      data-slot="tabs-panels"
      className={cn(
        "min-h-0 grow",
        "has-[>_*_>_[data-ending-style]]:ease-out-expo has-[>_*_>_[data-ending-style]]:transition-[height] has-[>_*_>_[data-ending-style]]:duration-400",
        className,
      )}
      {...props}
    >
      <div ref={innerRef} className="grid">
        {children}
      </div>
    </div>
  );
}

function TabsContent({
  className,
  disableAnimation = false,
  ...props
}: BaseTabs.Panel.Props & { disableAnimation?: boolean }) {
  return (
    <BaseTabs.Panel
      data-slot="tabs-content"
      className={cn(
        "min-w-0 flex-1 outline-none",
        "[grid-area:1/1]",
        !disableAnimation && [
          "ease-out-expo transition-[opacity,translate,filter] duration-[350ms,350ms,350ms]",
          // Enter/exit: fade + blur (scale with height diff via --fade-duration)
          "data-starting-style:opacity-0 data-starting-style:blur-sm",
          "data-ending-style:opacity-0 data-ending-style:blur-sm data-ending-style:contain-[size]",
          // Directional slide (fixed 400ms)
          "data-[activation-direction=right]:data-starting-style:translate-x-3",
          "data-[activation-direction=right]:data-ending-style:-translate-x-3",
          "data-[activation-direction=left]:data-starting-style:-translate-x-3",
          "data-[activation-direction=left]:data-ending-style:translate-x-3",
          "data-[activation-direction=down]:data-starting-style:translate-y-3",
          "data-[activation-direction=down]:data-ending-style:-translate-y-3",
          "data-[activation-direction=up]:data-starting-style:-translate-y-3",
          "data-[activation-direction=up]:data-ending-style:translate-y-3",
          // Fallback for none/initial mount
          "data-[activation-direction=none]:data-starting-style:translate-y-3",
          "data-[activation-direction=none]:data-ending-style:translate-y-3",
          "motion-reduce:blur-none motion-reduce:transition-none",
        ],
        className,
      )}
      {...props}
    />
  );
}

export { Tabs, TabsList, TabsTrigger, TabsPanels, TabsContent };
